def verify_links(apps, schema_editor):
    Attention = apps.get_model('activities', 'SocialAttention')
    attentions = Attention.objects.using(schema_editor.connection.alias)
    mismatches = attentions.filter(client_request__isnull=False).exclude(
        recipient_id=models.F('client_request__recipient_id'), delegation_id=models.F('client_request__delegation_id'),
    )
    if mismatches.exists():
        ids = ', '.join(map(str, mismatches.values_list('pk', flat=True)[:10]))
        raise RuntimeError(f'Atenciones con persona o delegación distinta a su folio: {ids}')


def link_cases(apps, schema_editor):
    alias = schema_editor.connection.alias
    requests = apps.get_model('activities', 'ClientRequest').objects.using(alias)
    cases = apps.get_model('activities', 'AttentionCase').objects.using(alias)
    attentions = apps.get_model('activities', 'SocialAttention').objects.using(alias)
    for request in requests.iterator(chunk_size=500):
        case, _ = cases.get_or_create(client_request_id=request.pk, defaults={
            'recipient_id': request.recipient_id, 'delegation_id': request.delegation_id, 'subject': request.subject,
        })
        cases.filter(pk=case.pk).update(created_at=request.created_at, updated_at=request.updated_at)
        attentions.filter(client_request_id=request.pk).update(case_id=case.pk)

    for attention in attentions.filter(case__isnull=True).select_related('attention_type').iterator(chunk_size=500):
        case = cases.create(recipient_id=attention.recipient_id, delegation_id=attention.delegation_id,
                            subject=attention.attention_type.name[:100], direct_status='RECORDED')
        cases.filter(pk=case.pk).update(created_at=attention.created_at, updated_at=attention.updated_at,
                                        deleted_at=attention.deleted_at)
        attentions.filter(pk=attention.pk).update(case_id=case.pk)


def restore_request_links(apps, schema_editor):
    Attention = apps.get_model('activities', 'SocialAttention')
    attentions = Attention.objects.using(schema_editor.connection.alias)
    for pk, request_id in attentions.values_list('pk', 'case__client_request_id').iterator(chunk_size=500):
        attentions.filter(pk=pk).update(client_request_id=request_id)


